            if grid[i][c] == fg_val:
                j = i + 1
                while j < rows and grid[j][c] == fg_val:
                    j += 1
                line_length = j - i
                found_lines.append(('v', i, c, j - 1, line_length))
                i = j
            else:
                i += 1

    # Diagonal down-right lines (r increases, c increases)
    for start_r in range(rows):
        for start_c in range(cols):
            if grid[start_r][start_c] == fg_val:
                path = [(start_r, start_c)]
                curr_r, curr_c = start_r, start_c
                while True:
                    next_r = curr_r + 1
                    next_c = curr_c + 1
                    if 0 <= next_r < rows and 0 <= next_c < cols and grid[next_r][next_c] == fg_val:
                        path.append((next_r, next_c))
                        curr_r, curr_c = next_r, next_c
                    else:
