                if len(path) >= 2:  # Only consider lines of length 2+
                    found_lines.append(('d+', tuple(path), len(path)))

    # Anti-diagonal lines (r increases, c decreases)
    for start_r in range(rows):
        for start_c in range(cols):
            if grid[start_r][start_c] == fg_val:
                path = [(start_r, start_c)]
                curr_r, curr_c = start_r, start_c
                while True:
